#include "ship_editor/ShipyardWorkspaceSystem.h"
#include <algorithm>
namespace subspace {
std::vector<EditorAssetCard>ShipyardWorkspaceSystem::BuildAssetCards(const std::vector<ShipyardModuleRecord>&c){std::vector<EditorAssetCard>o;for(const auto&r:c){EditorAssetCard a;a.assetId=r.source.moduleId;a.displayName=ShipyardPartTaxonomySystem::DisplayName(r);a.category=ShipyardModuleSystem::ClassName(r.moduleClass);a.subtitle=std::string(ShipyardModuleSystem::SemanticName(r.semantic))+" • "+ShipyardModuleSystem::SizeName(r.size);a.previewKey="shipyard:"+r.source.moduleId;a.tags={ShipyardModuleSystem::ClassName(r.moduleClass),ShipyardModuleSystem::SemanticName(r.semantic),ShipyardModuleSystem::SizeName(r.size)};if(!r.generatorEligible)a.badge="PCG QUARANTINED";o.push_back(std::move(a));}return o;}
std::vector<EditorOutlinerNode>ShipyardWorkspaceSystem::BuildOutliner(const std::vector<ShipyardModuleRecord>&c,const ProceduralShipVisualRecipe&r){std::vector<EditorOutlinerNode>o;o.push_back({"ship","","SHIP","Ship",true,false});for(std::size_t i=0;i<r.modules.size();++i){std::string l=r.modules[i].moduleId;for(const auto&x:c)if(x.source.moduleId==r.modules[i].moduleId){l=ShipyardPartTaxonomySystem::DisplayName(x);break;}std::string p="ship";for(const auto&a:r.attachments)if(a.childModuleIndex==i&&a.parentModuleIndex<r.modules.size()){p="module:"+std::to_string(a.parentModuleIndex);break;}o.push_back({"module:"+std::to_string(i),p,l,"ShipModule",true,false});}return o;}
std::vector<EditorPropertySection>ShipyardWorkspaceSystem::BuildInspector(const ShipyardModuleRecord*r,const VisualModulePlacement*p,ShipyardWorkspaceMode m,bool adv){std::vector<EditorPropertySection>o;if(!r&&m!=ShipyardWorkspaceMode::Test)return o;if(r){EditorPropertySection s{"summary","Summary",false,false,{}};s.properties.push_back({"name","Module",EditorPropertyType::ReadOnly,ShipyardPartTaxonomySystem::DisplayName(*r),{},"shipyard.module",true,false});s.properties.push_back({"semantic","Role",EditorPropertyType::ReadOnly,ShipyardModuleSystem::SemanticName(r->semantic),{},"shipyard.semantic",true,false});o.push_back(s);}if(m==ShipyardWorkspaceMode::Build&&p){EditorPropertySection t{"transform","Transform",false,false,{}};t.properties.push_back({"position","Position",EditorPropertyType::Text,std::to_string(p->x)+", "+std::to_string(p->y)+", "+std::to_string(p->z),{},"shipyard.transform",true,false});o.push_back(t);}if(m==ShipyardWorkspaceMode::Model){EditorPropertySection a{"model","Model",false,false,{}};a.properties.push_back({"geometry","Geometry",EditorPropertyType::ReadOnly,"Add Shape / Stretch / Modifiers / Region Selection",{},"shipyard.model",true,false});o.push_back(a);}if(m==ShipyardWorkspaceMode::Interior){EditorPropertySection a{"interior","Interior",false,false,{}};a.properties.push_back({"interior","Interior Program",EditorPropertyType::ReadOnly,"Decks / rooms / circulation / apertures / docking & hangars",{},"shipyard.interior",true,false});o.push_back(a);}if(m==ShipyardWorkspaceMode::Appearance){EditorPropertySection a{"appearance","Appearance",false,false,{}};a.properties.push_back({"paint","Paint Zones",EditorPropertyType::ReadOnly,"Primary / Secondary / Trim",{},"shipyard.appearance",true,false});o.push_back(a);}if(m==ShipyardWorkspaceMode::Systems&&r){EditorPropertySection a{"systems","Systems",false,false,{}};a.properties.push_back({"functional","Functional",EditorPropertyType::Bool,r->functional?"true":"false",{},"shipyard.systems",false,false});o.push_back(a);}if(m==ShipyardWorkspaceMode::Character){EditorPropertySection a{"character","Character",false,false,{}};a.properties.push_back({"animation","Animation",EditorPropertyType::ReadOnly,"Humanoid scale / animation retarget / preview",{},"shipyard.character",true,false});o.push_back(a);}if(m==ShipyardWorkspaceMode::Pcg){EditorPropertySection a{"pcgstudio","PCG Studio",false,false,{}};a.properties.push_back({"pcg","PCG",EditorPropertyType::ReadOnly,"Explain current canonical candidate / rejection / proof",{},"shipyard.pcgstudio",true,false});o.push_back(a);}if(m==ShipyardWorkspaceMode::World){EditorPropertySection a{"world","World",false,false,{}};a.properties.push_back({"terrain","Terrain",EditorPropertyType::ReadOnly,"Sculpt / Paint / Terraform",{},"shipyard.world",true,false});o.push_back(a);}if(m==ShipyardWorkspaceMode::DevWorld){EditorPropertySection a{"devworld","Dev World",false,false,{}};a.properties.push_back({"scene","Scene",EditorPropertyType::ReadOnly,"Scale / animation / PCG proving ground",{},"shipyard.devworld",true,false});o.push_back(a);}if(m==ShipyardWorkspaceMode::ProjectTools){EditorPropertySection a{"project_tools","Forge / Project Tools",false,false,{}};a.properties.push_back({"provider","Provider",EditorPropertyType::ReadOnly,"project.control.json / forge.project.v1",{},"shipyard.projecttools",true,false});o.push_back(a);}if(m==ShipyardWorkspaceMode::Authoring&&r){EditorPropertySection a{"authoring","Advanced Authoring",false,false,{}};a.properties.push_back({"sockets","Sockets",EditorPropertyType::ReadOnly,std::to_string(r->sockets.size()),{},"shipyard.sockets",true,false});a.properties.push_back({"pcg","PCG Eligible",EditorPropertyType::Bool,r->generatorEligible?"true":"false",{},"shipyard.pcg",true,false});o.push_back(a);}if(m==ShipyardWorkspaceMode::Test){EditorPropertySection a{"test","Play / Test",false,false,{}};a.properties.push_back({"interior","Interior FPS",EditorPropertyType::ReadOnly,"Spawn in the current persistent ship and walk the authored interior",{},"shipyard.test",true,false});a.properties.push_back({"cockpit","Cockpit 6DOF",EditorPropertyType::ReadOnly,"Take direct first-person flight control without leaving the authored ship identity",{},"shipyard.test",true,false});o.push_back(a);}if(adv&&r){EditorPropertySection a{"advanced","Advanced",true,true,{}};a.properties.push_back({"assetId","Asset ID",EditorPropertyType::ReadOnly,r->source.moduleId,{},"shipyard.advanced",true,true});o.push_back(a);}return o;}
std::vector<ShipyardWorkspaceMode> ShipyardWorkspaceSystem::PrimaryWorkspaces(){return {ShipyardWorkspaceMode::Build,ShipyardWorkspaceMode::Model,ShipyardWorkspaceMode::Interior,ShipyardWorkspaceMode::Systems,ShipyardWorkspaceMode::Appearance,ShipyardWorkspaceMode::Test};}
std::vector<ShipyardWorkspaceMode> ShipyardWorkspaceSystem::DeveloperWorkspaces(){return {ShipyardWorkspaceMode::Model,ShipyardWorkspaceMode::Character,ShipyardWorkspaceMode::Pcg,ShipyardWorkspaceMode::World,ShipyardWorkspaceMode::DevWorld,ShipyardWorkspaceMode::ProjectTools,ShipyardWorkspaceMode::Authoring};}
const char* ShipyardWorkspaceSystem::WorkspaceName(ShipyardWorkspaceMode m){switch(m){case ShipyardWorkspaceMode::Build:return"BUILD";case ShipyardWorkspaceMode::Interior:return"INTERIOR";case ShipyardWorkspaceMode::Systems:return"SYSTEMS";case ShipyardWorkspaceMode::Appearance:return"APPEARANCE";case ShipyardWorkspaceMode::Test:return"TEST";case ShipyardWorkspaceMode::Model:return"MODEL";case ShipyardWorkspaceMode::Character:return"CHARACTER";case ShipyardWorkspaceMode::Pcg:return"PCG LAB";case ShipyardWorkspaceMode::World:return"WORLD";case ShipyardWorkspaceMode::DevWorld:return"DEV WORLD";case ShipyardWorkspaceMode::ProjectTools:return"PROJECT TOOLS";case ShipyardWorkspaceMode::Authoring:return"AUTHORING";}return"BUILD";}
EditorHelpRegistry ShipyardWorkspaceSystem::BuildHelpRegistry(){EditorHelpRegistry h;h.Register({"shipyard.module","Module","Reusable kitbash module.","Drag it from the Asset Browser into the viewport to stage placement; release never silently commits attachment.","LMB / Drag"});h.Register({"shipyard.transform","Transform","Move, rotate, or scale the selected placed module.","View-space movement is default; Ship/Local are explicit alternatives.","W / E / R"});h.Register({"shipyard.sockets","Connections","Reusable mating points used for snapping and PCG.","Normal Build mode shows contextual connections; raw socket editing lives in Advanced Authoring.",""});h.Register({"shipyard.pcg","Teach PCG","Promote a corrected assembly as proof.","Proof preserves request, topology, interior, apertures, systems and validation lineage.",""});h.Register({"shipyard.appearance","Appearance","Paint, patterns, camouflage, decals, and faction livery.","Appearance works on semantic surface sections rather than raw material names.",""});h.Register({"shipyard.systems","Systems","Functional fitting and networks.","Integrity, power, heat, propulsion, weapons, shields, sensors and cargo compile from the canonical ship.",""});h.Register({"shipyard.model","Model","Native geometry creation and region articulation.","Add parametric shapes or select a sub-region for doors, ramps, antennas and other moving parts.",""});h.Register({"shipyard.pcgstudio","PCG Lab","Inspect the one canonical generator candidate.","Explain rejection reasons, topology and proof lineage without acting as a second generator.",""});h.Register({"shipyard.interior","Interior","Interior program and circulation.","Author rooms, corridors, stairs, ladders, elevators, airlocks, docking corridors and hangars against player scale.",""});h.Register({"shipyard.character","Character","Canonical player-scale and animation preview lane.","Character calibration is the ruler for doors, seats, consoles, decks and vehicles.",""});h.Register({"shipyard.devworld","Dev World","Large in-game proving ground.","Load a solar system or test scene while the Shipyard authoring layer remains available.",""});h.Register({"shipyard.projecttools","Forge / Project Tools","Native thin client for the project-owned PCC.","Commands come from forge.project.v1 and preserve their declared interpreter.",""});h.Register({"shipyard.test","Play / Test","Run the current authored ship in-place.","Walk the interior in FPS, take cockpit 6DOF control, or open Remote Fleet Command, then return to editing without creating a surrogate ship.","F5 / Play"});return h;}
SubspaceDockWorkspace ShipyardWorkspaceSystem::BuildDefaultDockWorkspace(){
    SubspaceDockWorkspace w;
    w.id="shipyard";
    w.rootNodeId="root";

    // First-class DCC default: global menu remains fixed above this tree.
    // Everything below it is represented as a dockable panel. The center
    // viewport is permanent; authoring panels can move, float, collapse or
    // auto-hide without creating a second layout authority.
    w.nodes={
        {"root",true,SubspaceDockSplitAxis::Vertical,.78f,"upper","bottom",{}, {},false},
        {"upper",true,SubspaceDockSplitAxis::Horizontal,.035f,"tool_left","center_right",{}, {},false},
        {"center_right",true,SubspaceDockSplitAxis::Horizontal,.80f,"center","right_stack",{}, {},false},
        {"right_stack",true,SubspaceDockSplitAxis::Vertical,.38f,"right_top","right_bottom",{}, {},false},
        {"tool_left",false,SubspaceDockSplitAxis::Horizontal,.5f,{},{},{},{},false},
        {"center",false,SubspaceDockSplitAxis::Horizontal,.5f,{},{},{},{},false},
        {"right_top",false,SubspaceDockSplitAxis::Horizontal,.5f,{},{},{},{},false},
        {"right_bottom",false,SubspaceDockSplitAxis::Horizontal,.5f,{},{},{},{},false},
        {"bottom",false,SubspaceDockSplitAxis::Horizontal,.5f,{},{},{},{},false}
    };

    auto add=[&](const char*id,const char*title,const char*leaf,bool visible,float opacity,
                 float preferredW,float preferredH,bool closable=true,bool floatable=true,bool resizable=true){
        SubspaceDockPanel p;
        p.id=id;p.title=title;p.defaultLeafId=leaf;p.visible=visible;p.opacity=opacity;
        p.closable=closable;p.floatable=floatable;p.resizable=resizable;
        p.preferredWidth=preferredW;p.preferredHeight=preferredH;
        p.minWidth=std::min(150.0f,preferredW);p.minHeight=std::min(90.0f,preferredH);
        p.hoverReveal=true;
        SubspaceDockSystem::RegisterPanel(w,p);
    };
    add("tool_rail","Tools","tool_left",true,.98f,48,420,false,false,true);
    add("viewport","3D Viewport","center",true,.18f,900,620,false,false,false);
    add("outliner","Outliner","right_top",true,.94f,340,240);
    add("properties","Properties","right_bottom",true,.96f,380,460);
    add("asset_browser","Asset Browser","bottom",true,.96f,900,220);
    add("generator","Generator","bottom",false,.96f,520,320);
    add("modeling","Modeling","right_bottom",false,.96f,420,460);
    add("articulation","Attachments & Pivots","right_bottom",false,.96f,420,400);
    add("interior_program","Interior Program","right_bottom",false,.96f,420,460);
    add("apertures_hangars","Apertures & Hangars","right_bottom",false,.96f,420,460);
    add("systems","Systems","right_bottom",false,.96f,420,460);
    add("material_library","Materials & Paint","right_bottom",false,.96f,420,460);
    add("material_audit","Material Health","bottom",false,.94f,560,240);
    add("kitbash_intake","Kitbash Intake","bottom",false,.94f,620,280);
    add("history","History","bottom",false,.94f,520,220);
    add("validation","Validation","bottom",false,.94f,520,220);
    add("console","Console","bottom",false,.92f,620,240);
    add("playtest","Play / Test","bottom",false,.94f,520,240);
    add("forge_project_tools","Forge / Project Tools","bottom",false,.94f,620,260);
    return w;
}
std::vector<ShipyardSurfaceSection>ShipyardWorkspaceSystem::DefaultSurfaceSections(const ShipyardModuleRecord&r){std::vector<ShipyardSurfaceSection>o;ShipyardSurfaceSection h;h.id="hull.primary";h.sourceMaterial="*";h.semantic="HullPrimary";h.primaryPaint=h.pattern=h.decal=h.factionLivery=true;o.push_back(h);if(r.semantic==ShipyardModuleSemantic::MainEngine||r.semantic==ShipyardModuleSemantic::EngineNozzle||r.semantic==ShipyardModuleSemantic::RcsThruster){ShipyardSurfaceSection n;n.id="propulsion.nozzle";n.semantic="Nozzle";n.trimPaint=n.emissiveOverride=true;o.push_back(n);}if(r.semantic==ShipyardModuleSemantic::CommandCockpit||r.semantic==ShipyardModuleSemantic::CommandBridge){ShipyardSurfaceSection g;g.id="command.glass";g.semantic="GlassCanopy";g.needsReview=true;o.push_back(g);}return o;}
ShipyardModuleItemDefinition ShipyardWorkspaceSystem::BuildItemDefinition(const ShipyardModuleRecord&r){ShipyardModuleItemDefinition i;i.moduleId=r.source.moduleId;i.displayName=ShipyardPartTaxonomySystem::DisplayName(r);float v=std::max(.01f,(r.source.halfWidth*2)*(r.source.halfLength*2)*(r.source.halfHeight*2));i.mass=v*.9f;i.hitPoints=80+v*95+(r.primaryHull?180:0);i.powerDraw=r.functional?5:0;i.heat=r.semantic==ShipyardModuleSemantic::MainEngine?18:(r.functional?4:0);i.rarity=r.generatorEligible?0:2;i.manufacturer="Subspace Certified";i.iconKey="module:"+r.source.moduleId;return i;}
}
